package com.nicole.stillin;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.webkit.*;import java.io.*;import org.json.*;
public class MainActivity extends Activity {
 WebView web;Handler ui=new Handler(Looper.getMainLooper());boolean photoAfterPermission=false;String pendingExport;final String ORIGIN="https://app.stillin.local";
 boolean own(Uri u){return "https".equals(u.getScheme())&&"app.stillin.local".equals(u.getHost());}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);web=new WebView(this);web.setBackgroundColor(Color.rgb(16,13,16));setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.getSettings().setMediaPlaybackRequiresUserGesture(true);web.addJavascriptInterface(new Bridge(),"StillAndroid");web.setWebViewClient(new WebViewClient(){
 @Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(own(u))return false;if(r.isForMainFrame()&&"https".equals(u.getScheme()))try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}
 @Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(!own(u))return blocked();String p=u.getPath();if(p==null||"/".equals(p))p="/index.html";if(p.contains("..")||p.indexOf('\\')>=0)return blocked();try{String mime=p.endsWith(".js")?"application/javascript":p.endsWith(".css")?"text/css":p.endsWith(".svg")?"image/svg+xml":"text/html";return new WebResourceResponse(mime,"UTF-8",getAssets().open("www"+p));}catch(Exception e){return blocked();}}
 @Override public void onPageFinished(WebView v,String url){if(own(Uri.parse(url)))v.evaluateJavascript("window.onNativeResume&&window.onNativeResume()",null);}
 });web.loadUrl(ORIGIN+"/index.html");State.channels(this);State.schedule(this);}
 WebResourceResponse blocked(){return new WebResourceResponse("text/plain","UTF-8",403,"Blocked",null,new ByteArrayInputStream(new byte[0]));}
 @Override protected void onResume(){super.onResume();if(web!=null){web.onResume();web.evaluateJavascript("window.onNativeResume&&window.onNativeResume()",null);}State.schedule(this);}
 @Override protected void onPause(){if(web!=null)web.onPause();super.onPause();}
 @Override public void onBackPressed(){web.evaluateJavascript("(function(){const d=document.querySelector('dialog[open]');if(d){d.close();return true}return false})()",r->{if(!"true".equals(r))super.onBackPressed();});}
 void permission(String type){if("notifications".equals(type)){if(Build.VERSION.SDK_INT>=33&&!getSystemService(NotificationManager.class).areNotificationsEnabled())requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},11);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}else if("alarms".equals(type)&&Build.VERSION.SDK_INT>=31)startActivity(new Intent(Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())));}
 void camera(){if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){photoAfterPermission=true;requestPermissions(new String[]{Manifest.permission.CAMERA},12);return;}startActivityForResult(new Intent(this,PrivateCamera.class),22);}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] results){super.onRequestPermissionsResult(r,p,results);if(r==12&&photoAfterPermission){photoAfterPermission=false;if(results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED)camera();else web.evaluateJavascript("window.onNativePhoto&&window.onNativePhoto(null)",null);}State.schedule(this);web.evaluateJavascript("window.onNativeResume&&window.onNativeResume()",null);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==22){File f=new File(getCacheDir(),"private-capture.jpg");String value="null";try{if(result==RESULT_OK&&f.exists()){byte[] bytes=java.nio.file.Files.readAllBytes(f.toPath());value=JSONObject.quote("data:image/jpeg;base64,"+android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP));}}catch(Exception ignored){}finally{f.delete();}web.evaluateJavascript("window.onNativePhoto&&window.onNativePhoto("+value+")",null);}if(request==33&&pendingExport!=null){String dataOut=pendingExport;pendingExport=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null)try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(dataOut.getBytes(java.nio.charset.StandardCharsets.UTF_8));web.evaluateJavascript("toast('Private export saved')",null);}catch(Exception e){web.evaluateJavascript("toast('Export could not be saved')",null);}}}
 public final class Bridge {
 @JavascriptInterface public String getState(){return State.raw(MainActivity.this);}
 @JavascriptInterface public String saveState(String json){return State.save(MainActivity.this,json);}
 @JavascriptInterface public String status(){try{JSONObject s=new JSONObject();s.put("notifications",getSystemService(NotificationManager.class).areNotificationsEnabled());s.put("exact",State.exact(MainActivity.this));return s.toString();}catch(Exception e){return "{}";}}
 @JavascriptInterface public void permission(String type){ui.post(()->MainActivity.this.permission(type));}
 @JavascriptInterface public void takePhoto(){ui.post(()->camera());}
 @JavascriptInterface public void testAlarm(){State.test(MainActivity.this);}
 @JavascriptInterface public void exportData(String json){if(json.length()>100000000)return;ui.post(()->{pendingExport=json;startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"still-in-private-export.json"),33);});}
 }
}
